import ghidra.app.decompiler.*; import ghidra.app.script.GhidraScript; import ghidra.program.model.listing.*;
public class OwnerCommitTail extends GhidraScript { public void run()throws Exception{DecompInterface d=new DecompInterface();d.openProgram(currentProgram);long[] a={0x00425a70L,0x0041a2d0L,0x00425800L};for(long x:a){Function f=getFunctionContaining(toAddr(x));println("\n=== "+toAddr(x)+" "+(f==null?"<missing>":f.getName())+" ===");if(f!=null){DecompileResults r=d.decompileFunction(f,150,monitor);if(r.getDecompiledFunction()!=null)println(r.getDecompiledFunction().getC());}}d.dispose();}}
